"use client";

import { useState } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { Eye, EyeOff } from "lucide-react";
import { createClient } from "@/lib/supabase/browser";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

/**
 * Staff & Admin Sign-In — strictly via assigned username (email) and password.
 *
 * Admin login addresses (@abeokutapolo2026.ng) are autogenerated usernames and
 * do not receive email or SMS codes. If an administrator has a password or
 * sign-in problem, the Super Admin clicks "Approve" next to their name in
 * Admin Hierarchy (/abawole/admins) to restore access and issue a password.
 */
export function SignInForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  /** Routes the signed-in officer or gate marshal to their designated area. */
  async function routeOnward(userEmail?: string) {
    const next = searchParams.get("next");
    if (next && next.startsWith("/")) {
      router.push(next);
      return;
    }
    try {
      const supabase = createClient();
      const { data: roleRows } = await supabase
        .from("user_role_assignments")
        .select("role_key, expires_at, revoked_at")
        .eq("user_id", (await supabase.auth.getUser()).data.user?.id ?? "");

      const now = Date.now();
      const activeRoles = (roleRows || [])
        .filter((r) => !r.revoked_at && (!r.expires_at || new Date(r.expires_at).getTime() > now))
        .map((r) => r.role_key);

      const normalizedEmail = (userEmail || email).toLowerCase().trim();
      const isAbawoleRole =
        activeRoles.some((r) =>
          [
            "super_admin",
            "president",
            "general_secretary",
            "finance_officer",
            "accreditation_officer",
          ].includes(r),
        ) ||
        normalizedEmail === "secretary@abeokutapolo2026.ng" ||
        normalizedEmail === "president@abeokutapolo2026.ng" ||
        normalizedEmail === "superadmin@abeokutapolo2026.ng" ||
        normalizedEmail === "finsec@abeokutapolo2026.ng" ||
        normalizedEmail === "finance@abeokutapolo2026.ng" ||
        normalizedEmail === "admin@abeokutapolo2026.ng";

      const isScanRole =
        activeRoles.includes("security_checkin_officer") ||
        normalizedEmail.startsWith("gate@") ||
        normalizedEmail.startsWith("gate1@") ||
        normalizedEmail.startsWith("gate2@") ||
        normalizedEmail.startsWith("gate3@");

      if (isAbawoleRole) {
        router.push("/abawole");
      } else if (isScanRole) {
        router.push("/scan");
      } else {
        router.push("/dashboard");
      }
    } catch {
      router.push("/dashboard");
    }
  }

  async function submitPassword(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setPending(true);

    try {
      const supabase = createClient();
      const { data: authData, error: signInError } = await supabase.auth.signInWithPassword({
        email: email.trim().toLowerCase(),
        password,
      });

      if (signInError) {
        setError(
          "That username and password did not match. Please check them and try again, or ask the Super Admin to click 'Approve' next to your name in Admin Hierarchy.",
        );
        return;
      }

      await routeOnward(authData.user?.email);
      router.refresh();
    } catch (err) {
      console.error("Sign-in error:", err);
      setError(
        err instanceof Error
          ? err.message
          : "Sign-in is currently unavailable. Please try again.",
      );
    } finally {
      setPending(false);
    }
  }

  return (
    <form onSubmit={submitPassword} className="flex flex-col gap-4">
      <div className="flex flex-col gap-2">
        <Label htmlFor="email">Username (Assigned Admin Email)</Label>
        <Input
          id="email"
          type="email"
          autoComplete="username"
          placeholder="e.g. president@abeokutapolo2026.ng"
          required
          value={email}
          onChange={(e) => setEmail(e.target.value)}
        />
      </div>

      <div className="flex flex-col gap-2">
        <div className="flex items-center justify-between">
          <Label htmlFor="password">Password</Label>
          <button
            type="button"
            onClick={() => setShowPassword((prev) => !prev)}
            className="inline-flex items-center gap-1 text-xs font-medium text-forest-interactive hover:underline"
          >
            {showPassword ? (
              <>
                <EyeOff className="h-3.5 w-3.5" />
                <span>Hide</span>
              </>
            ) : (
              <>
                <Eye className="h-3.5 w-3.5" />
                <span>Show</span>
              </>
            )}
          </button>
        </div>
        <Input
          id="password"
          type={showPassword ? "text" : "password"}
          autoComplete="current-password"
          required
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
      </div>

      {error ? (
        <p
          role="alert"
          className="rounded border border-danger/40 bg-danger/10 px-3 py-2 text-sm text-danger"
        >
          {error}
        </p>
      ) : null}

      <Button type="submit" disabled={pending} className="w-full">
        {pending ? "Signing in…" : "Sign in"}
      </Button>

      <p className="text-center text-xs text-muted-brand leading-relaxed">
        Having a password or sign-in problem? Ask the Super Admin to click{" "}
        <strong className="text-forest">Approve</strong> next to your name in Admin Hierarchy.
      </p>
    </form>
  );
}
